package fr.loto.cartons;
import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
public class MainActivity extends Activity {
 Game game=new Game(); LinearLayout root,cards,entry; TextView input;String digits="";static final int PICK=12,PICK_REPLACE=13; boolean startupPromptVisible=true; final Handler promptHandler=new Handler(Looper.getMainLooper());
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(128);load();render();promptHandler.postDelayed(()->{startupPromptVisible=false;render();},30000);}
 TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setGravity(Gravity.CENTER);t.setPadding(5,8,5,8);return t;}
 Button button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setOnClickListener(v->r.run());return b;}
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+0.5f);}
 GradientDrawable bg(int color,int stroke){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setStroke(dp(1),stroke);d.setCornerRadius(dp(2));return d;}
 GradientDrawable round(int c){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(10));return d;}
 Button styled(String name,int color,int ink,int size,Runnable click){Button b=button(name,click);b.setTextSize(size);b.setTypeface(null,Typeface.BOLD);b.setTextColor(ink);b.setBackground(round(color));return b;}
 void editLast(){if(game.drawn.isEmpty()){toast("Aucun tirage à modifier");return;}int old=game.drawn.get(game.drawn.size()-1);EditText field=new EditText(this);field.setInputType(2);field.setText(""+old);field.selectAll();new AlertDialog.Builder(this).setTitle("Modifier le dernier numéro : "+old).setView(field).setNegativeButton("Annuler",null).setPositiveButton("Valider",(d,w)->{try{game.replace(old,Integer.parseInt(field.getText().toString()));digits="";save();render();}catch(Exception e){toast("Numéro invalide ou déjà tiré");}}).show();}
 void render(){root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(0xffedf4ff);if(Build.VERSION.SDK_INT>=30){root.setOnApplyWindowInsetsListener((v,insets)->{android.graphics.Insets bars=insets.getInsets(WindowInsets.Type.systemBars());v.setPadding(bars.left,bars.top,bars.right,bars.bottom);return insets;});}else{root.setFitsSystemWindows(true);}setContentView(root);LinearLayout toolbar=new LinearLayout(this);toolbar.setPadding(dp(5),dp(5),dp(5),dp(3));root.addView(toolbar,new LinearLayout.LayoutParams(-1,dp(65)));
 toolbar.addView(styled("▤ IMPORTER DES CARTONS PDF",0xff064d9e,Color.WHITE,14,()->openPdfPicker()),new LinearLayout.LayoutParams(0,-1,3));
 LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,-1,1);cp.setMargins(dp(4),0,dp(4),0);toolbar.addView(styled("⇄ CHANGER DE FEUILLE",0xff465f7d,Color.WHITE,12,()->openPdfPicker(true)),cp);
 toolbar.addView(styled("DÉMARQUER",0xffae2034,Color.WHITE,12,()->new AlertDialog.Builder(this).setTitle("Effacer tous les tirages ?").setNegativeButton("Annuler",null).setPositiveButton("Confirmer",(d,w)->{game.clear();game.mode=1;digits="";save();render();}).show()),new LinearLayout.LayoutParams(0,-1,1));
 LinearLayout modes=new LinearLayout(this);modes.setPadding(dp(38),dp(3),dp(38),dp(3));root.addView(modes,new LinearLayout.LayoutParams(-1,dp(58)));
 for(int i=1;i<=3;i++){final int m=i;Button stage=styled(i==1?"1 LIGNE":i==2?"2 LIGNES":"CARTON PLEIN",game.mode==m?0xff0961cc:Color.WHITE,game.mode==m?Color.WHITE:0xff132f56,15,()->{if(game.mode!=m){game.mode=m;save();render();}});LinearLayout.LayoutParams mp=new LinearLayout.LayoutParams(0,-1,1);mp.setMargins(dp(3),0,dp(3),0);modes.addView(stage,mp);}
 boolean wide=getResources().getConfiguration().orientation==2;LinearLayout body=new LinearLayout(this);body.setOrientation(wide?0:1);root.addView(body,new LinearLayout.LayoutParams(-1,0,1));
 ScrollView scroll=new ScrollView(this);cards=new LinearLayout(this);cards.setOrientation(1);scroll.addView(cards);body.addView(scroll,new LinearLayout.LayoutParams(wide?0:-1,wide?-1:0,wide?7:1));
 entry=new LinearLayout(this);entry.setOrientation(1);entry.setPadding(dp(6),dp(5),dp(6),dp(5));entry.setBackground(round(0xff17528d));LinearLayout.LayoutParams ep=new LinearLayout.LayoutParams(wide?0:-1,wide?-1:dp(360),wide?3:0);ep.setMargins(dp(3),0,dp(3),0);body.addView(entry,ep);
 TextView label=text("Numéro (1 à 90)",18);label.setTextColor(Color.WHITE);label.setTypeface(null,Typeface.BOLD);entry.addView(label,new LinearLayout.LayoutParams(-1,dp(42)));
 LinearLayout numberRow=new LinearLayout(this);entry.addView(numberRow,new LinearLayout.LayoutParams(-1,dp(103)));
 input=text(digits.isEmpty()?"—":digits,48);input.setTextColor(0xff09264b);input.setTypeface(null,Typeface.BOLD);input.setBackground(round(Color.WHITE));numberRow.addView(input,new LinearLayout.LayoutParams(0,-1,3));
 LinearLayout tools=new LinearLayout(this);tools.setOrientation(1);LinearLayout.LayoutParams tp=new LinearLayout.LayoutParams(0,-1,2);tp.setMargins(dp(4),0,0,0);numberRow.addView(tools,tp);
 tools.addView(styled("⌫",0xff304e72,Color.WHITE,20,()->key("⌫")),new LinearLayout.LayoutParams(-1,0,1));
 LinearLayout.LayoutParams fp=new LinearLayout.LayoutParams(-1,0,1);fp.setMargins(0,dp(3),0,0);tools.addView(styled("✎ Modifier le dernier",0xff294569,Color.WHITE,11,()->editLast()),fp);
 LinearLayout pad=new LinearLayout(this);pad.setOrientation(1);LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(-1,0,1);pp.topMargin=dp(4);entry.addView(pad,pp);
 String[][] keys={{"1","2","3"},{"4","5","6"},{"7","8","9"},{"Effacer","0","OK ✓"}};
 for(String[] line:keys){LinearLayout row=new LinearLayout(this);pad.addView(row,new LinearLayout.LayoutParams(-1,wide?0:dp(49),wide?1:0));for(String key:line){int color=key.equals("Effacer")?0xffc51f2d:key.startsWith("OK")?0xff06951c:0xfff5f8ff;int ink=key.equals("Effacer")||key.startsWith("OK")?Color.WHITE:0xff09264b;Button digit=styled(key,color,ink,key.equals("Effacer")?12:23,()->key(key));LinearLayout.LayoutParams kp=new LinearLayout.LayoutParams(0,-1,1);kp.setMargins(dp(3),dp(3),dp(3),dp(3));row.addView(digit,kp);}}
showCards();LinearLayout history=new LinearLayout(this);history.setGravity(Gravity.CENTER_VERTICAL);history.setPadding(dp(10),0,dp(10),0);history.setBackground(round(0xff3d6d9e));root.addView(history,new LinearLayout.LayoutParams(-1,dp(52)));TextView ht=text("Derniers numéros :",15);ht.setTextColor(Color.WHITE);ht.setTypeface(null,Typeface.BOLD);history.addView(ht);for(int j=game.drawn.size()-1;j>=Math.max(0,game.drawn.size()-5);j--){TextView n=text(""+game.drawn.get(j),17);n.setTextColor(Color.WHITE);n.setTypeface(null,Typeface.BOLD);n.setBackground(round(0xff092a55));LinearLayout.LayoutParams hp=new LinearLayout.LayoutParams(dp(49),dp(38));hp.setMargins(dp(4),0,0,0);history.addView(n,hp);}checkWin();}
 void key(String k){if(k.equals("Effacer")){digits="";}else if(k.equals("⌫")){if(!digits.isEmpty())digits=digits.substring(0,digits.length()-1);}else if(k.startsWith("OK")){if(!digits.isEmpty()){int n=Integer.parseInt(digits);if(n>=1&&n<=90&&!game.drawn.contains(n)){game.add(n);digits="";save();render();return;}toast("Numéro invalide ou déjà tiré");}}else if(digits.length()<2)digits+=k;input.setText(digits.isEmpty()?"—":digits);}
 interface Callback{void accept(int n);}void numberDialog(String title,Callback cb){EditText e=new EditText(this);e.setInputType(2);new AlertDialog.Builder(this).setTitle(title).setView(e).setNegativeButton("Annuler",null).setPositiveButton("OK",(d,w)->{try{cb.accept(Integer.parseInt(e.getText().toString()));}catch(Exception ex){toast("Numéro invalide");}}).show();}
 void showCards(){ArrayList<Game.Card> list=new ArrayList<>(game.cards);list.sort((a,b)->Integer.compare(game.missing(a),game.missing(b)));if(list.isEmpty())cards.addView(text("Importer un PDF de cartons",22));for(int i=0;i<list.size();i++)cards.addView(cardView(list.get(i),i==0));}
 LinearLayout cardView(Game.Card c,boolean large){
  LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(6),dp(7),dp(6),dp(9));box.setBackgroundColor(large?0xffe5f0fc:0xfff2f2f2);
  TextView heading=text("CARTON N° "+c.id+"   •   "+game.missing(c)+" manquant(s)",large?18:15);
  heading.setTextColor(0xff172b46);heading.setTypeface(null,Typeface.BOLD);heading.setPadding(dp(2),dp(4),dp(2),dp(6));box.addView(heading);
  for(int[] line:c.grid){LinearLayout row=new LinearLayout(this);row.setOrientation(0);box.addView(row,new LinearLayout.LayoutParams(-1,dp(large?56:46)));
   for(int n:line){TextView cell=new TextView(this);cell.setText(n==0?"":String.valueOf(n));cell.setTextSize(large?21:18);cell.setTextColor(Color.BLACK);cell.setTypeface(null,Typeface.BOLD);cell.setGravity(Gravity.CENTER);cell.setPadding(0,0,0,0);cell.setIncludeFontPadding(false);cell.setMaxLines(1);
    int fill=n!=0&&game.drawn.contains(n)?0xffa9e9b7:n==0?0xffeeeeee:Color.WHITE;cell.setBackground(bg(fill,0xff555555));
    LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,-1,1);cp.setMargins(dp(1),dp(1),dp(1),dp(1));row.addView(cell,cp);
   }
  }
  LinearLayout.LayoutParams outer=new LinearLayout.LayoutParams(-1,-2);outer.setMargins(dp(4),dp(5),dp(4),dp(7));box.setLayoutParams(outer);return box;
 }
 void checkWin(){for(Game.Card c:game.cards)if(game.winner(c)&&!game.acknowledged.contains(game.winKey(c))){new AlertDialog.Builder(this).setTitle("GAGNANT ! Carton "+c.id).setView(cardView(c,true)).setCancelable(false).setPositiveButton("VÉRIFICATION OK",(d,w)->{game.acknowledged.add(game.winKey(c));save();render();}).show();break;}}
 void openPdfPicker(){openPdfPicker(false);}void openPdfPicker(boolean replace){int request=replace?PICK_REPLACE:PICK;try{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/pdf");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(i,request);}catch(Exception e){try{Intent i=new Intent(Intent.ACTION_GET_CONTENT);i.setType("application/pdf");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(Intent.createChooser(i,"Choisir un PDF dans la tablette"),request);}catch(Exception ex){new AlertDialog.Builder(this).setTitle("Explorateur indisponible").setMessage(ex.getMessage()).setPositiveButton("OK",null).show();}}}
 void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if((request!=PICK&&request!=PICK_REPLACE)||result!=RESULT_OK||data==null)return;final boolean replacing=request==PICK_REPLACE;Uri uri=data.getData();if(uri==null){toast("Aucun fichier sélectionné");return;}try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}new Thread(()->{try{ArrayList<Game.Card> imported=PdfImporter.read(this,uri);runOnUiThread(()->{if(replacing){if(imported.isEmpty()){toast("Aucun carton trouvé : feuille précédente conservée");return;}game.cards.clear();game.acknowledged.clear();}int added=0;for(Game.Card c:imported){boolean exists=false;for(Game.Card x:game.cards)if(x.id.equals(c.id))exists=true;if(!exists){game.cards.add(c);added++;}}save();render();toast(added+" cartons importés. Vérifie leur contenu.");});}catch(Exception e){runOnUiThread(()->new AlertDialog.Builder(this).setTitle("Import impossible").setMessage(e.getMessage()).setPositiveButton("OK",null).show());}}).start();}
 void save(){try{JSONObject o=new JSONObject();o.put("mode",game.mode);JSONArray cs=new JSONArray();for(Game.Card c:game.cards){JSONObject j=new JSONObject();j.put("id",c.id);JSONArray rows=new JSONArray();for(int[] row:c.grid){JSONArray nums=new JSONArray();for(int n:row)nums.put(n);rows.put(nums);}j.put("grid",rows);cs.put(j);}o.put("cards",cs);o.put("drawn",new JSONArray(game.drawn));o.put("ack",new JSONArray(game.acknowledged));getPreferences(0).edit().putString("state",o.toString()).apply();}catch(Exception ignored){}}
 void load(){try{JSONObject o=new JSONObject(getPreferences(0).getString("state","{}"));game.mode=o.optInt("mode",1);JSONArray cs=o.optJSONArray("cards");if(cs!=null)for(int i=0;i<cs.length();i++){JSONObject j=cs.getJSONObject(i);Game.Card c=new Game.Card(j.getString("id"));JSONArray rows=j.getJSONArray("grid");for(int r=0;r<3;r++)for(int k=0;k<9;k++)c.grid[r][k]=rows.getJSONArray(r).getInt(k);game.cards.add(c);}JSONArray d=o.optJSONArray("drawn");if(d!=null)for(int i=0;i<d.length();i++)game.drawn.add(d.getInt(i));JSONArray a=o.optJSONArray("ack");if(a!=null)for(int i=0;i<a.length();i++)game.acknowledged.add(a.getString(i));}catch(Exception ignored){}}
}